//! Amiga media rules (design v3.0 §3.5.1, §3.5.3) through the public API only, on disks generated by
//! `tests/tools/mkadf.py` and zips built here: no core, no network, no third-party data. Complements the unit
//! tests of `media.rs` with realistic 880 KB images and the puae rules from `cores.toml`.

use std::fs::{self, File};
use std::io::Write;
use std::path::{Path, PathBuf};
use std::process::Command;

use emu_runtime::{
    MediaPolicy, MediaRules, MediaSet, RuntimeError, prepare_media, reset_core_game_files,
};
use tempfile::TempDir;
use zip::write::SimpleFileOptions;

/// Extensions accepted by the puae binary (what `retro_get_system_info` would report).
const PUAE_EXTS: [&str; 9] = [
    "adf", "adz", "dms", "fdi", "ipf", "hdf", "lha", "m3u", "zip",
];

fn exts(with_zip: bool) -> Vec<String> {
    PUAE_EXTS
        .iter()
        .filter(|e| with_zip || **e != "zip")
        .map(|e| (*e).to_owned())
        .collect()
}

fn puae_rules() -> MediaRules {
    MediaRules {
        policy: MediaPolicy::WorkingCopy,
        media_direct: vec!["ipf".into(), "lha".into()],
        max_copy_bytes: emu_runtime::MAX_COPY_BYTES,
        m3u_launch: emu_runtime::M3uLaunch::None,
        multi_disc: emu_runtime::MultiDisc::Playlist,
    }
}

fn mkadf() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../../tests/tools/mkadf.py")
}

/// Blank labelled disk made by the project's generator.
fn make_adf(path: &Path, label: &str) {
    fs::create_dir_all(path.parent().unwrap()).unwrap();
    let out = Command::new("python3")
        .args(["-I"])
        .arg(mkadf())
        .args(["--label", label])
        .arg(path)
        .env("SOURCE_DATE_EPOCH", "1700000000")
        .output()
        .expect("python3 is required for the Amiga media tests");
    assert!(
        out.status.success(),
        "mkadf.py failed: {}",
        String::from_utf8_lossy(&out.stderr)
    );
    assert_eq!(fs::metadata(path).unwrap().len(), 901_120);
}

fn build_zip(path: &Path, entries: &[(&str, &[u8])]) {
    fs::create_dir_all(path.parent().unwrap()).unwrap();
    let mut zip = zip::ZipWriter::new(File::create(path).unwrap());
    for (name, data) in entries {
        zip.start_file(*name, SimpleFileOptions::default()).unwrap();
        zip.write_all(data).unwrap();
    }
    zip.finish().unwrap();
}

struct Env {
    dir: TempDir,
}

impl Env {
    fn new() -> Self {
        Self {
            dir: tempfile::tempdir().unwrap(),
        }
    }
    fn roms(&self) -> PathBuf {
        self.dir.path().join("roms/amiga")
    }
    fn saves(&self) -> PathBuf {
        self.dir.path().join("saves/puae")
    }
}

fn set(name: &str, images: Vec<PathBuf>) -> MediaSet {
    MediaSet {
        name: name.into(),
        images,
        playlist: None,
        launch: None,
    }
}

/// Every regular file under `root`, with its bytes: the "hash before / after" of the user's files.
fn snapshot(root: &Path) -> Vec<(PathBuf, Vec<u8>)> {
    fn walk(dir: &Path, out: &mut Vec<(PathBuf, Vec<u8>)>) {
        let mut entries: Vec<_> = fs::read_dir(dir)
            .unwrap()
            .map(|e| e.unwrap().path())
            .collect();
        entries.sort();
        for path in entries {
            if path.is_dir() {
                walk(&path, out);
            } else {
                let bytes = fs::read(&path).unwrap();
                out.push((path, bytes));
            }
        }
    }
    let mut out = Vec::new();
    walk(root, &mut out);
    out
}

#[test]
fn two_disks_become_working_copies_and_a_playlist() {
    let env = Env::new();
    let d1 = env.roms().join("Game/Disk 1.adf");
    let d2 = env.roms().join("Game/Disk 2.adf");
    make_adf(&d1, "DISK1");
    make_adf(&d2, "DISK2");
    let before = snapshot(&env.roms());

    let p = prepare_media(
        &set("Game", vec![d1.clone(), d2.clone()]),
        &puae_rules(),
        &exts(true),
        &env.saves(),
    )
    .unwrap();

    let work = env.saves().join("Game.disks");
    assert_eq!(p.work_dir.as_deref(), Some(work.as_path()));
    assert_eq!(p.images, [work.join("Disk 1.adf"), work.join("Disk 2.adf")]);
    assert_eq!(p.content, work.join("Game.m3u"));
    assert_eq!(
        fs::read_to_string(&p.content).unwrap(),
        "Disk 1.adf\nDisk 2.adf\n"
    );
    // The copies equal the sources; the core may scribble on them, the originals stay as they were.
    assert_eq!(fs::read(&p.images[0]).unwrap(), fs::read(&d1).unwrap());
    fs::write(&p.images[0], b"the core wrote here").unwrap();
    fs::write(&p.images[1], b"and here").unwrap();
    assert_eq!(snapshot(&env.roms()), before);

    // Second launch: the existing copies (the player's progress) are reused untouched.
    let again = prepare_media(
        &set("Game", vec![d1, d2]),
        &puae_rules(),
        &exts(true),
        &env.saves(),
    )
    .unwrap();
    assert_eq!(again, p);
    assert_eq!(fs::read(&p.images[0]).unwrap(), b"the core wrote here");
    assert_eq!(snapshot(&env.roms()), before);
}

#[test]
fn a_zip_of_disks_is_extracted_even_when_the_core_reads_zips() {
    let env = Env::new();
    let adf = env.dir.path().join("src/a.adf");
    make_adf(&adf, "FROMZIP");
    let bytes = fs::read(&adf).unwrap();
    let zip = env.roms().join("Pack.zip");
    build_zip(&zip, &[("Disk A.adf", &bytes), ("readme.txt", b"hi")]);
    let before = snapshot(&env.roms());

    let p = prepare_media(
        &set("Pack", vec![zip]),
        &puae_rules(),
        &exts(true),
        &env.saves(),
    )
    .unwrap();
    let work = env.saves().join("Pack.disks");
    assert_eq!(p.images, [work.join("Disk A.adf")]);
    assert_eq!(fs::read(&p.images[0]).unwrap(), bytes);
    assert_eq!(snapshot(&env.roms()), before);
}

#[test]
fn a_zip_without_image_is_passed_whole_or_refused() {
    let env = Env::new();
    let zip = env.roms().join("Data.zip");
    build_zip(&zip, &[("data.bin", b"1"), ("notes.txt", b"2")]);
    let before = snapshot(&env.roms());

    // Core declaring `zip`: the archive goes to the core as it is (a copy under WorkingCopy).
    let p = prepare_media(
        &set("Data", vec![zip.clone()]),
        &puae_rules(),
        &exts(true),
        &env.saves(),
    )
    .unwrap();
    assert_eq!(fs::read(&p.content).unwrap(), fs::read(&zip).unwrap());
    assert!(p.content.starts_with(env.saves()));

    // Core without `zip`: refused, nothing handed to the core.
    for policy in [MediaPolicy::WorkingCopy, MediaPolicy::Direct] {
        let rules = MediaRules {
            policy,
            ..puae_rules()
        };
        let err = prepare_media(
            &set("Data2", vec![zip.clone()]),
            &rules,
            &exts(false),
            &env.saves(),
        )
        .unwrap_err();
        assert!(matches!(err, RuntimeError::NoContentInArchive(_)), "{err}");
    }
    assert_eq!(snapshot(&env.roms()), before);
}

#[test]
fn direct_extensions_are_referenced_in_place_and_a_direct_zip_is_never_opened() {
    let env = Env::new();
    let adf = env.roms().join("G/Disk 1.adf");
    make_adf(&adf, "DISK1");
    let ipf = env.roms().join("G/Disk 2.ipf");
    fs::write(&ipf, b"CAPS fake ipf").unwrap();
    let zip = env.roms().join("G/Whd.zip");
    build_zip(&zip, &[("inside.adf", b"x")]);
    let before = snapshot(&env.roms());

    let mut rules = puae_rules();
    let p = prepare_media(
        &set("G", vec![adf, ipf.clone()]),
        &rules,
        &exts(true),
        &env.saves(),
    )
    .unwrap();
    let work = env.saves().join("G.disks");
    assert_eq!(p.images, [work.join("Disk 1.adf"), ipf.clone()]);
    assert!(p.images[1].is_absolute());
    assert!(!work.join("Disk 2.ipf").exists());

    // `zip` listed as direct: the archive is handed over in place, never extracted nor copied.
    rules.media_direct.push("zip".into());
    let p = prepare_media(
        &set("Z", vec![zip.clone()]),
        &rules,
        &exts(true),
        &env.saves(),
    )
    .unwrap();
    assert_eq!(p.content, zip);
    assert_eq!(p.work_dir, None);
    assert!(!env.saves().join("Z.disks").exists());
    assert_eq!(snapshot(&env.roms()), before);
}

#[test]
fn user_playlist_keeps_only_whitelisted_directives() {
    let env = Env::new();
    let d1 = env.roms().join("Multi/a.adf");
    let d2 = env.roms().join("Multi/b.adf");
    make_adf(&d1, "A");
    make_adf(&d2, "B");
    let m3u = env.roms().join("Multi/Multi.m3u");
    fs::write(
        &m3u,
        "#EXTM3U\n# a comment\na.adf|Disk A\n#SAVEDISK:Multi\n#COMMAND:RUN \"X\"\n#LABEL:Side B\nb.adf\n#EXTINF:1,x\n",
    )
    .unwrap();
    let before = snapshot(&env.roms());

    let p = prepare_media(
        &MediaSet {
            name: "Multi".into(),
            images: Vec::new(),
            playlist: Some(m3u),
            launch: None,
        },
        &puae_rules(),
        &exts(true),
        &env.saves(),
    )
    .unwrap();
    let text = fs::read_to_string(&p.content).unwrap();
    assert_eq!(
        text,
        "a.adf|Disk A\n#SAVEDISK:Multi\n#LABEL:Side B\nb.adf\n"
    );
    assert!(!text.contains("COMMAND") && !text.contains("EXTINF") && !text.contains("comment"));
    assert_eq!(p.images.len(), 2);
    assert_eq!(snapshot(&env.roms()), before);
}

#[test]
fn a_source_over_the_copy_limit_is_refused_before_anything_is_written() {
    let env = Env::new();
    let adf = env.roms().join("Big.adf");
    make_adf(&adf, "BIG");
    let rules = MediaRules {
        max_copy_bytes: 1024,
        m3u_launch: emu_runtime::M3uLaunch::None,
        multi_disc: emu_runtime::MultiDisc::Playlist,
        ..puae_rules()
    };
    let err = prepare_media(&set("Big", vec![adf]), &rules, &exts(true), &env.saves()).unwrap_err();
    assert!(matches!(err, RuntimeError::InvalidMediaSet(_)), "{err}");
    let leftovers: Vec<_> = fs::read_dir(env.saves().join("Big.disks"))
        .map(|d| d.map(|e| e.unwrap().file_name()).collect())
        .unwrap_or_default();
    assert!(
        leftovers
            .iter()
            .all(|n: &std::ffi::OsString| n.to_string_lossy().starts_with('.')),
        "{leftovers:?}"
    );
}

#[test]
fn consoles_and_atari_st_rules_are_unchanged() {
    // Direct policy without direct extensions (every console, ST under hatariB): files pass through in place.
    let env = Env::new();
    let rom = env.dir.path().join("roms/snes/Game.sfc");
    fs::create_dir_all(rom.parent().unwrap()).unwrap();
    fs::write(&rom, b"rom").unwrap();
    let exts = vec!["sfc".to_owned(), "smc".to_owned(), "zip".to_owned()];
    let p = prepare_media(
        &set("Game", vec![rom.clone()]),
        &MediaRules::new(MediaPolicy::Direct),
        &exts,
        &env.saves(),
    )
    .unwrap();
    assert_eq!(p.content, rom);
    assert_eq!(p.images, [rom]);
    assert_eq!(p.work_dir, None);
    assert!(p.temp_dir().is_none());
    assert!(!env.saves().exists());

    // hatari: working copies, no direct extension, zip not declared (2.0 behaviour).
    let st = env.dir.path().join("roms/atarist/Game.st");
    fs::create_dir_all(st.parent().unwrap()).unwrap();
    fs::write(&st, b"st disk").unwrap();
    let p = prepare_media(
        &set("Game", vec![st.clone()]),
        &MediaRules::new(MediaPolicy::WorkingCopy),
        &["st".to_owned(), "msa".to_owned()],
        &env.dir.path().join("saves/hatari"),
    )
    .unwrap();
    assert_eq!(
        p.content,
        env.dir.path().join("saves/hatari/Game.disks/Game.st")
    );
    assert_eq!(fs::read(&st).unwrap(), b"st disk");
}

#[test]
fn reset_core_game_files_removes_only_the_games_save_disks() {
    let env = Env::new();
    let saves = env.saves();
    fs::create_dir_all(saves.join("Game.disks")).unwrap();
    let keep = [
        "Game.disks/Game (1).adf",
        "Other.save1.adf",
        "Game.sav",
        "Game2.save1.adf",
        "Game.save1.adf.bak",
    ];
    for name in keep {
        fs::write(saves.join(name), b"keep").unwrap();
    }
    for name in ["Game.save1.adf", "Game.save2.adf"] {
        fs::write(saves.join(name), b"save disk").unwrap();
    }
    let outside = env.dir.path().join("saves/Game.save1.adf");
    fs::write(&outside, b"not in the core folder").unwrap();

    let removed = reset_core_game_files(&saves, "Game", &["{game}.save*.adf".to_owned()]).unwrap();
    assert_eq!(
        removed,
        [saves.join("Game.save1.adf"), saves.join("Game.save2.adf")]
    );
    for name in keep {
        assert!(saves.join(name).exists(), "{name}");
    }
    assert!(outside.exists());

    // Hostile patterns and names: refused, nothing deleted.
    fs::write(saves.join("Game.save9.adf"), b"x").unwrap();
    for pattern in ["../*", "{game}/*", "*", "{game}.*.*", "..", "{game}\\x*"] {
        let r = reset_core_game_files(&saves, "Game", &[pattern.to_owned()]);
        assert!(
            matches!(r, Err(RuntimeError::InvalidMediaSet(_))),
            "{pattern}"
        );
    }
    for name in ["../Game", "a/b", "..", ""] {
        let r = reset_core_game_files(&saves, name, &["{game}.save*.adf".to_owned()]);
        assert!(r.is_err(), "{name}");
    }
    assert!(saves.join("Game.save9.adf").exists());
    assert!(outside.exists());
}

#[cfg(unix)]
#[test]
fn reset_core_game_files_never_follows_links() {
    let env = Env::new();
    let saves = env.saves();
    fs::create_dir_all(&saves).unwrap();
    let victim = env.dir.path().join("precious.adf");
    fs::write(&victim, b"user data").unwrap();
    std::os::unix::fs::symlink(&victim, saves.join("Game.save1.adf")).unwrap();
    let removed = reset_core_game_files(&saves, "Game", &["{game}.save*.adf".to_owned()]).unwrap();
    assert!(removed.is_empty());
    assert_eq!(fs::read(&victim).unwrap(), b"user data");
}
